package io.nekohasekai.sfa.bg

// Kept free of Android classes so low-API rejection and all binding failures
// are exercised by local JVM tests before the actual APK assembly.
internal fun <Network> bindPlatformNetworkInterface(
    sdk: Int,
    fd: Int,
    interfaceName: String?,
    resolve: (String) -> Network?,
    bind: (Network, Int) -> Unit,
) {
    if (sdk < 23) {
        throw UnsupportedOperationException("android: interface binding requires API23; API$sdk is unsupported")
    }
    require(fd >= 0) { "android: invalid bind descriptor" }
    val name = interfaceName?.takeIf { it.isNotEmpty() }
        ?: throw IllegalArgumentException("android: missing bind interface")
    val network = resolve(name)
        ?: error("android: network interface unavailable: $interfaceName")
    bind(network, fd) // Preserve errors; never report an empty-success bind.
}

package io.nekohasekai.sfa.bg

import org.junit.Assert.*
import org.junit.Test

class PlatformNetworkBindingTest {
    @Test fun api21And22RejectBeforeNetworkResolutionOrBinding() {
        for (sdk in listOf(21, 22)) {
            try {
                bindPlatformNetworkInterface<String>(sdk, 7, "wlan0",
                    resolve = { throw AssertionError("low API resolved Network") },
                    bind = { _, _ -> throw AssertionError("low API called bindSocket") })
                fail("low API silently accepted binding")
            } catch (expected: UnsupportedOperationException) {
                assertTrue(expected.message!!.contains("API$sdk"))
            }
        }
    }

    @Test fun api23AndLaterBindTheResolvedNetworkAndOriginalDescriptor() {
        for (sdk in listOf(23, 24, 35)) {
            var calls = 0
            bindPlatformNetworkInterface(sdk, 17, "wlan0",
                resolve = { assertEquals("wlan0", it); "exact-network" },
                bind = { network, fd -> assertEquals("exact-network", network); assertEquals(17, fd); calls++ })
            assertEquals(1, calls)
        }
    }

    @Test fun supportedApiMissingNetworkDoesNotReportSuccess() {
        try {
            bindPlatformNetworkInterface<String>(23, 7, "missing",
                resolve = { null }, bind = { _, _ -> fail("bound missing network") })
            fail("missing network silently accepted")
        } catch (expected: IllegalStateException) {
            assertTrue(expected.message!!.contains("unavailable"))
        }
    }

    @Test fun supportedApiBindFailurePropagatesWithoutSuccess() {
        val failure = SecurityException("network binding denied")
        try {
            bindPlatformNetworkInterface(23, 7, "wlan0", resolve = { "network" }, bind = { _, _ -> throw failure })
            fail("bind failure swallowed")
        } catch (actual: SecurityException) { assertSame(failure, actual) }
    }

    @Test fun invalidDescriptorAndNameAreRejectedBeforeResolution() {
        for ((fd, name) in listOf(-1 to "wlan0", 7 to "", 7 to null)) {
            try {
                bindPlatformNetworkInterface<String>(23, fd, name,
                    resolve = { throw AssertionError("invalid input resolved Network") }, bind = { _, _ -> fail("invalid input bound") })
                fail("invalid binding input accepted")
            } catch (expected: IllegalArgumentException) { }
        }
    }
}

